MONO="font-family: 'IBM Plex Mono', monospace; font-size: 11px; letter-spacing: 0.03em; text-transform: uppercase;"
BIG="font-family: 'Archivo Black', sans-serif; letter-spacing: -0.065em; line-height: 0.86; text-transform: uppercase;"
ARROW='<svg width="22" height="14" viewBox="0 0 22 14" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M0 7h20M14 1l6 6-6 6"></path></svg>'
BACK='<a href="#" aria-label="Back" style="display: flex; width: 40px; height: 40px; align-items: center; justify-content: center; color: currentColor"><svg width="22" height="14" viewBox="0 0 22 14" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M22 7H2M8 1L2 7l6 6"></path></svg></a>'
GLASS="background: linear-gradient(160deg, rgba(255,255,255,0.24), rgba(255,255,255,0.06)); border: 1px solid rgba(255,255,255,0.5); box-shadow: inset 0 1px 0.5px rgba(255,255,255,0.65), 0 8px 24px rgba(0,0,0,0.25); backdrop-filter: blur(16px) saturate(180%); -webkit-backdrop-filter: blur(16px) saturate(180%);"
def btn(label,dark=True,arrow=True,flex=False,extra=''):
    bg='background: #0d0d0d; color: #FFFFFF;' if dark else 'background: #F2F2F2; color: #0d0d0d;'
    return f'<a href="#" data-b="{label}" style="display: flex; align-items: center; justify-content: center; gap: 10px; height: 58px; border-radius: 29px; {bg} text-decoration: none; {MONO} font-size: 12px; {"flex: 1;" if flex else ""}{extra}">{label}{(" "+ARROW) if arrow else ""}</a>'
def wbtn(label):
    return f'<a href="#" data-b="{label}" style="display: flex; align-items: center; justify-content: center; gap: 10px; height: 58px; border-radius: 29px; background: #FFFFFF; color: #0d0d0d; text-decoration: none; {MONO} font-size: 12px">{label} {ARROW}</a>'
def chip(t,on=False,col='#0d0d0d'):
    st=f'background: {col}; color: #FFFFFF;' if on else 'background: #F2F2F2; color: #0d0d0d;'
    return f'<span data-chip style="display: inline-flex; align-items: center; height: 36px; padding: 0 14px; border-radius: 18px; {st} {MONO} cursor: pointer">{t}</span>'
def shell(inner,bg='#FFFFFF',fg='#0d0d0d'):
    return f'<div style="position: relative; width: 100%; height: 100%; box-sizing: border-box; overflow-y: auto; overflow-x: hidden; scrollbar-width: none; background: {bg}; color: {fg}; font-family: \'Archivo Narrow\', sans-serif">{inner}</div>'
def q(n,head,body,cta='NEXT',second=None,note=''):
    bars=''.join(f'<span style="flex: 1; height: 3px; border-radius: 2px; background: {"#0d0d0d" if i<n else "rgba(13,13,13,0.15)"}"></span>' for i in range(9))
    foot=f'<div style="position: absolute; left: 16px; right: 16px; bottom: 30px; display: flex; gap: 8px">{btn(second,False,False,True) if second else ""}{btn(cta,True,True,True)}</div>'
    return shell(f'''<div style="position: absolute; left: 16px; right: 16px; top: 22px; display: flex; align-items: center; gap: 10px">{BACK}<div style="flex: 1; display: flex; gap: 4px">{bars}</div><span style="{MONO}">{n:02d}/09</span></div>
<div style="position: absolute; left: 16px; right: 16px; top: 84px"><div style="{MONO}">Question {n:02d}{(" · "+note) if note else ""}</div><div style="{BIG} font-size: 46px; margin-top: 8px">{head}</div></div>
<div style="position: absolute; left: 16px; right: 16px; top: 300px; bottom: 110px; overflow-y: auto">{body}</div>{foot}''')
def field(ph,val=''):
    return f'<div contenteditable="true" data-ph="{ph}" style="padding: 18px; background: #F7F7F7; min-height: 120px; box-sizing: border-box; font-size: 19px; line-height: 1.45; outline: none">{val}</div>'
def opt(t,sub='',on=False):
    subdiv=('<div style="font-size: 15px; color: #555; margin-top: 4px">'+sub+'</div>') if sub else ''
    return f'<a href="#" data-opt style="display: block; padding: 16px 0; border-top: 1px solid rgba(13,13,13,0.15); color: #0d0d0d; text-decoration: none"><div style="display: flex; justify-content: space-between; align-items: center"><span style="font-family: \'Archivo Black\', sans-serif; letter-spacing: -0.05em; font-size: 24px; text-transform: uppercase">{t}</span><span class="dot" style="width: 22px; height: 22px; border-radius: 50%; border: 1.5px solid #0d0d0d; background: {"#0d0d0d" if on else "transparent"}"></span></div>{subdiv}</a>'
S={}
S['q01']=q(1,'What should<br>we call our<br>cover star?',field('Your first name','Megan')+f'<div style="{MONO} margin-top: 12px; color: #666">It goes on the cover of your Issue.</div>')
S['q03']=q(3,'What do you<br>want most<br>this year?',''.join(opt(t,s,i==0) for i,(t,s) in enumerate([('Financial freedom','Money that gives me choices'),('A home I love','Space that feels like me'),('Real love','Being chosen, choosing back'),('My own thing','A business, a studio, a name'),('Peace','Calm, health, nothing to prove')])))
