S['q06']=q(6,'How do you<br>want to feel<br>every day?',f'<div style="display: flex; flex-wrap: wrap; gap: 8px">'+''.join(chip(t,t in ('Unbothered','Rich','Chosen'),'#F65AAD') for t in ['Unbothered','Rich','Chosen','Free','Powerful','Soft','Seen','Calm','Magnetic'])+'</div>')
S['q08']=q(8,'Name one<br>thing you<br>already made<br>happen.',field('e.g. I moved cities on my own.','I left the job that made me small.')+f'<div style="{MONO} margin-top: 12px; color: #666">Your first proof. It opens your Issue.</div>',note='Proof')
